{
  "data_as_of": "2026-11-04",
  "examples": [
    {
      "report_number": "13-03653-91",
      "facility": "Atlanta VA Medical Center, Decatur, GA",
      "commitment": "Nursing staff ensure medication carts are secured at all times. Medication carts are secured in a locked medication room unless in use. The BCMA Coordinator conducts routine rounding in all inpatient areas to ensure and document compliance."
    },
    {
      "report_number": "15-00606-495",
      "facility": "Battle Creek VA Medical Center, Battle Creek, MI",
      "commitment": "Inpatient Mental Health Medication Nurses will check to ensure all drawers are securely locked on the medication cart following each opening of the cart. Nurse Managers will conduct random checks on each medication cart weekly until 100% compliance has been achieved for a 90‑day period."
    }
  ]
}
